-- Phase B.5 - verified course catalogue
--
-- 77 curated resources from DataCamp, Microsoft Learn, IBM SkillsBuild,
-- Cisco Networking Academy, freeCodeCamp, Coursera, Udemy, edX, Google, Khan Academy
-- and qualified YouTube courses/playlists.
--
-- Every URL was checked at build time. Availability is explicit per row:
--   free                          no payment required
--   free_with_limitations         free access with a real restriction (account, first chapter, labs)
--   audit                         free to audit; certificate costs extra
--   free_course_paid_certificate  course content free, certificate paid
--   paid                          payment required
--   youtube_free                  free YouTube video/playlist
--
-- Coursera and Udemy are never marked free. The catalogue is idempotent:
-- re-applying it updates the same rows and never duplicates them.

ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  provider = EXCLUDED.provider,
  provider_url = EXCLUDED.provider_url,
  category = EXCLUDED.category,
  level = EXCLUDED.level,
  duration_hours = EXCLUDED.duration_hours,
  language = EXCLUDED.language,
  url = EXCLUDED.url,
  availability = EXCLUDED.availability,
  availability_note = EXCLUDED.availability_note,
  format = EXCLUDED.format,
  description = EXCLUDED.description,
  is_verified = EXCLUDED.is_verified,
  verified_at = EXCLUDED.verified_at,
  updated_at = now();

-- Skill mapping -----------------------------------------------------------
ON CONFLICT (course_id, skill_name) DO UPDATE SET importance = EXCLUDED.importance;

-- Role mapping ------------------------------------------------------------
ON CONFLICT (course_id, role_slug) DO UPDATE SET relevance_score = EXCLUDED.relevance_score;

-- Remove obsolete seed rows from earlier drafts, never user rows. The
-- catalogue ids are all prefixed and are replaced wholesale only when the
-- id is no longer part of this catalogue.
DELETE FROM public.course_roles WHERE course_id NOT IN (SELECT id FROM public.courses);
DELETE FROM public.course_skills WHERE course_id NOT IN (SELECT id FROM public.courses);
